import {RULES,BODY_LIMITS} from './model-rules.js';
import {ACTION_DURATIONS,SUBSTEPS,DT} from './action-timing.js';
import {STRUCTURAL_DEFAULTS,STRUCTURE_RULES as S} from './brain-structure-rules.js';
import {initialConnectionBudget,initialLayerCounts} from './brain-initialization.js';
import {STRUCTURAL_TYPE_LAYOUT} from './structural-brain.js';
import {MUTATION_RULES} from './mutation-parameters.js';
import {formatGuideParameter} from './guide-parameters.js';
import {v,p,a,table,details} from './guide-markup.js';

const bound=key=>`<span class="guide-value" data-guide-param="${key}">${formatGuideParameter(key)}</span>`;
/** Выбранная для объяснения таблица, не настройка основателей. */
export function guideTopologyExample(){const layers=initialLayerCounts([2,0,1]);return {layers,...initialConnectionBudget(layers,100)};}
const topology=guideTopologyExample();
export const GUIDE_GENETICS_TEXT={
 'guide-birth-body':
 p('Рождение — отдельное действие, которое выбирает мозг из допустимых. Его доступность не заставляет жителя родить. Для старта должны одновременно выполняться пороги тела, зрелость, интервал после прошлых родов и ограничение числа живых.')
 +table('Пороговые значения выбранного контекста',['Условие старта','Значение'],[
 ['Энергия не ниже',bound('birthEnergy')],['Здоровье не ниже',bound('birthHealth')],
 ['Возраст не меньше',bound('maturity')],['После предыдущих родов прошло не меньше',bound('birthInterval')]])
 +p(`Роды занимают ${v(ACTION_DURATIONS[9]/SUBSTEPS,'Т')}. Во время этого процесса малая сеть не запрашивает добровольный пересмотр. Усвоение и ход возраста продолжаются; при гибели до завершения ребёнок не появляется.`)
 +'<h4>Пример: население успело достичь лимита</h4>'
 +p('Два жителя начали доступные роды, пока население ещё было ниже лимита. Первый завершил раньше, и живых стало достаточно для запрета новых родов. Уже начавшийся процесс второго не отменяется только из-за этого: в конце не повторяется весь набор стартовых порогов. Поэтому лимит мягкий и может быть превышен завершениями начатых процессов.')
 +details('Завершение и состояние ребёнка',
 p(`В конце требуется живой родитель с энергией не меньше разовой цены ${v(RULES.birthCost)}. Эта сумма списывается при завершении; обычной подшаговой ставки родов нет. Отдельно повторять исходные пороги энергии/здоровья, зрелость и лимит на завершении нельзя: действующий код их не проверяет.`)
 +p(`Ребёнок возникает на клетке родителя с ${v(RULES.newbornEnergy,'энергии')} и ${v(BODY_LIMITS.health,'здоровья')}, пустыми инвентарём и желудком. Он начинает принимать решения на следующем подшаге длительностью ${v(DT,'Т')}. Возраст, число детей, память и личные поправки начинаются заново. У основателя начальная энергия иная: ${v(RULES.initialEnergy)}.`)
 +p('Обновляются число детей родителя, возраст предыдущих родов, поколение и родословная. Идентификатор основателя связывает линию, а не один неизменный геном: потомки могут мутировать. История рождения ребёнка и позднейшая статистика его собственной жизни — разные записи.'))
 +p(`Связанные темы: ${a('genome','наследование')}, ${a('structure-evolution','структурная мутация')}, ${a('actions','процесс и срыв')}, ${a('research','показатели потомства')}.`),

 'guide-genome-body':
 p('Геном задаёт наследуемую основу организма. В текущей схеме он содержит не только веса сети, но и её изменяемую топологию, свойства ощущений/памяти/обучения, малую сеть вызова и регуляторы мутации. Длина генома зависит от получившейся структуры.')
 +table('Семейства наследуемых данных',['Семейство','Что задаёт'],[
 ['Исходные веса и смещения','Кодирование клеток, оценку ситуации, операции/цели и прямую оценку.'],
 ['Топология контекста','Скрытые нейроны, уровни и направленные связи.'],
 ['Чувствительности','Знаки и относительные вклады энергии, здоровья и желудка.'],
 ['Память и обучение','Ёмкости, давность/закрепление, скорость, забывание, след и дисконт.'],
 ['Контроллер вызова','Наследуемые веса малой сети пересмотра процесса.'],
 ['Регуляторы мутации','Вероятность и сила численных изменений; отдельная вероятность изменения структуры.']])
 +'<h4>Пример: ребёнок обучавшегося родителя</h4>'
 +p('Родитель изменил свои личные поправки после опыта. При рождении берётся его генетическая основа, к ней применяются разрешённые мутации. Накопленные поправки, карты памяти и следы не копируются. Если мутации выключены, геном ребёнка совпадает с основой родителя, но это не делает их текущие состояния мозга одинаковыми: ребёнок ещё не имеет его опыта.')
 +details('Численные мутации и наследуемая изменчивость',
 p('Обычная мутация рассматривает наследуемые числа с вероятностью, заданной родителем, и меняет выбранные значения случайной прибавкой. Для общих свойств используются более медленные вероятность и сила, чем для отдельных весов. Пределы валидатора ограничивают веса; регуляторы имеют собственные преобразования и диапазоны.')
 +p(`Вероятность не опускается ниже ${v(MUTATION_RULES.rateFloor*100,'%')}, сила — ниже <code>${MUTATION_RULES.strengthFloor.toExponential()}</code>. Начальные диапазоны основателей не являются пределами последующего развития. В геноме хранятся логарифмические координаты регуляторов; показанная вероятность и сила — преобразованные значения.`)
 +p('Регуляторы тоже могут мутировать. Правила данного рождения фиксируются по родителю до изменения ребёнка: новая вероятность ребёнка не применяется задним числом к его собственному созданию. Отдельный переключатель структурных мутаций позволяет сохранить численные изменения без перестройки схемы.'))
 +details('Случайный основатель и геном из файла',
 p('У случайных основателей веса создаются симметрично без назначенного предпочтения пищи или ожидания. Загруженный геном задаёт наследуемую основу. Указанные пользователем коэффициенты чувствительности заменяют только выбранные поля основы или случайного генома; остальные гены сохраняют свой источник. Это начальное условие основателей, а не постоянный запрет мутации у потомков.')
 +p(`Текущий геном имеет схему v${v(STRUCTURAL_TYPE_LAYOUT.version)}. Смысл массива определяется metadata и точной раскладкой, а не только длиной. Историческая константа GENOME_VERSION не служит единственным номером всех поддерживаемых схем. Валидность старого файла для анализа не означает его совместимость с новым миром. Неподдерживаемые версии нельзя автоматически читать как нынешние числа.`))
 +p(`Связанные темы: ${a('structure-evolution','структурные изменения')}, ${a('learning','личный опыт')}, ${a('genome-analysis','чтение генома и схемы')}, ${a('selection','рождение')}.`),

 'guide-structure-evolution-body':
 p('Эволюционирует главный контекст мозга. Кодировщик клеток, проекции и малая сеть имеют свою фиксированную форму. Схема ребёнка может отличаться при рождении; в течение жизни меняются веса, а не набор нейронов и связей.')
 +table('Старт и пределы',['Настройка','Смысл'],[
 ['Максимум нейронов / слоёв',`Верхние пределы изменяемого блока; базовые значения ${v(STRUCTURAL_DEFAULTS.maxNeurons)} и ${v(STRUCTURAL_DEFAULTS.maxLayers)}. Это не размер всех сетей вместе.`],
 ['Таблица нейронов','Число по каждому скрытому слою; сумма не превышает максимум. Нулевые столбцы убираются из фактической схемы.'],
 ['Процент связей','Число рёбер относительно полной связности соседних непустых уровней. Это не независимый шанс каждого ребра.'],
 ['Случайный старт без заданной таблицы',`Обычно ${v(S.founderNeuronsMin)}…${v(S.founderNeuronsMax)} скрытых нейронов с полными соседними связями, если пределы это допускают.`]])
 +'<h4>Пример: таблица 2, 0, 1</h4>'
 +p(`Рабочая нормировка оставляет уровни ${topology.layers.map(n=>v(n)).join(' → ')}. Для такой таблицы 100% соответствуют ${v(topology.base,'связям')}; полный набор всех разрешённых направленных связей — ${v(topology.maximum)}. До 100% выбирается заданное число соседних связей, выше добавляются пропуски уровней. Верхний допустимый процент зависит от таблицы. Ноль процентов означает отсутствие связей, но смещения выходов и другие части мозга остаются.`)
 +details('Одно структурное событие при рождении',
 p(`Вероятность структурной мутации — отдельный наследуемый ген; начальное случайное значение лежит от ${v(S.initialProbabilityMin*100)} до ${v((S.initialProbabilityMin+S.initialProbabilitySpan)*100,'%')}. При событии может измениться не больше одного скрытого нейрона и до ${v(S.maxConnectionChanges)} независимых связей. Возможен и вариант только с изменениями связей; недопустимая правка при достигнутом пределе не обязана состояться.`)
 +p('Новый нейрон помещается в существующий или новый слой в пределах ограничений. Ему добавляются обязательные входящая и исходящая связи; они входят в общий бюджет и защищены от удаления в том же событии. Входящий вес ненулевой, исходящий — нулевой: новые входы не меняют старые оценки немедленно. Старая ветвь не разрывается.')
 +p('Нулевой исходящий вес может измениться обучением или наследуемой мутацией. В первый момент градиент некоторых входящих весов новой ветви может быть нулевым; ненулевой градиент всех её весов сразу не гарантирован. При удалении нейрона все его связи удаляются вне бюджета независимых правок; опустевшие уровни сжимаются.'))
 +details('Допустимые связи и цена',
 p('Разрешены только связи вперёд: соседние уровни, пропуски и прямые вход→выход. Обратные связи и циклы запрещены; связи внутри одного уровня не создаются. Ноль скрытых нейронов допустим. Схема компилируется в порядок вычисления при создании мозга, а не перестраивается на каждом подшаге.')
 +p('Существующая нулевая связь отличается от отсутствующей. Число хранимых нейронов/связей и объём реально задействованного пути к выходам тоже могут различаться. Вычислительный счётчик использует план работы; статистика структуры описывает геном. Изменения средней структуры популяции могут отражать как мутации, так и отбор разных линий.'))
 +p(`Связанные темы: ${a('brain-structure','прямой проход')}, ${a('brain-cost','цена')}, ${a('genome','численные мутации')}, ${a('genome-analysis','визуальная схема')}.`),

 'guide-genome-analysis-body':
 p('Живую схему и файл генома читают по-разному. У выбранного жителя есть текущие личные поправки и память; в геноме хранится наследуемая основа. Просмотр структуры сам по себе не запускает выбор, не обучает мозг и не расходует его случайность.')
 +'<h4>Посмотреть мозг жителя</h4><ol>'
 +'<li>Во вкладке «Мир» выберите жителя и откройте его схему. Малое изображение показывает выбранный блок целиком.</li>'
 +'<li>Нажмите изображение, чтобы открыть большой диалог. Колёсико приближает/отдаляет, перетаскивание левой кнопкой перемещает схему. Кнопка вписывания возвращает общий вид.</li>'
 +'<li>Короткое нажатие выбирает нейрон или связь. Выбранные связи становятся белыми и толще; сведения об элементе показывают его назначение и вес. Для точного выбора можно использовать список элементов.</li>'
 +'<li>Переключайте блоки и читайте их пояснения. Стрелки клавиатуры перемещают схему, плюс/минус меняют масштаб, Home возвращает вписывание. После закрытия остаётся выбранный житель.</li></ol>'
 +details('Как читать цвет и числа',
 p('Зелёная связь имеет положительный действующий вес, жёлтая — отрицательный, серая — нулевой. Действующий вес складывается из основы и используемой личной поправки. При выключенном обучении личная поправка не участвует в оценивании. Знак отдельной связи не определяет полезность поведения: после неё есть другие связи и преобразования.')
 +p('Схема показывает устройство и веса, а не текущие активации. Числа в названиях внутренних проекций не обозначают закреплённые цели. Точные значения и единицы признаков объяснены в главе устройства мозга. Наибольшее отдаление вмещает блок, приближение ограничено для удобного разбора нескольких нейронов.'))
 +'<h4>Пример: сравнить два генома</h4>'
 +p('В «Анализе генома» загрузите первый файл в A, второй в B. Посмотрите версию/архитектуру, свойства и их преобразования; затем сравнение общих параметров и различий. Положительная разность B−A означает большее значение, а не доказанное улучшение. Отсутствующее или несопоставимое поле отличается от нуля.')
 +table('Поля анализатора',['Поле','Как читать'],[
 ['Версия, тип, схема, число генов','Определяют смысл массива и допустимость сопоставления.'],
 ['Индекс и сырое число','Место и значение в наследуемом массиве, до преобразования в свойство.'],
 ['Пересчитанное свойство','Например, скорость или вместимость по именованной шкале.'],
 ['Доля шкалы чувств','Относительный знаковый вклад чувствительности; не вероятность действия.'],
 ['Структура и регуляторы','Размеры схемы и вероятности/силы мутации в своих единицах.'],
 ['Источник, условия, отпечаток','Контекст экспорта, если был записан; отсутствие не заполняется предположением.']])
 +details('Файл не восстанавливает поведение целиком',
 p('Анализатор сначала проверяет формат, схему и полноту. Сетевой геном не превращается в таблицу вероятностей из одних весов: для этого нужны тело, обзор, память и личные поправки. Старые табличные геномы могут иметь отдельную таблицу сырых оценок, но и она не равна текущим вероятностям действий.')
 +p('Отчёт можно экспортировать в JSON или Markdown. Это отчёт анализатора, а не полный мир. Загрузка в анализатор сама по себе не назначает геном основой текущего мира; основы эксперимента выбираются в его плане. Небольшие отличия генов не доказывают небольшого отличия поведения — это исследуется сопоставимыми опытами.'))
 +p(`Связанные темы: ${a('genome','состав генома')}, ${a('structure-evolution','рост схемы')}, ${a('feelings','проценты предпочтений')}, ${a('research','сравнение опытов')}.`),
};
